import{_ as l,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Performance Meeting 2022-03-24","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-03-24","date":"2022-03-24T00:00:00.000Z","updated":"2022-03-30T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","PG日志","BlueStore"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-03-24.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-03-24.md","lastUpdated":1780460162000}'),r={name:"posts/2022/Ceph_Performance_Meeting_2022-03-24.md"};function o(n,e,s,p,c,u){return i(),a("div",null,[...e[0]||(e[0]=[t('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p>本次Ceph性能会议主要讨论了Ceph存储系统的性能问题、PG日志优化以及相关的技术细节。与会人员包括核心开发团队成员，讨论了多个Pull Request（PR）的更新和新PR的引入。</p><h3 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h3><ol><li><p><strong>性能回归问题</strong>：</p><ul><li>讨论了Gabriel的PR，旨在修复No Column B代码在特定情况下默认使用位图分配器的问题，以解决性能回归问题。</li><li>进行了Quincy与Pacific版本的性能测试，发现长时间运行下存在显著的性能回归。</li><li>讨论了可能的解决方案，包括在发布前快速修复No Column B或在后续版本中重新启用。</li></ul></li><li><p><strong>PG日志优化</strong>：</p><ul><li>讨论了PG日志和PG信息的优化，特别是减少对RocksDB资源的依赖。</li><li>提出了将PG日志写入缓冲区的方案，以减少写放大问题。</li><li>讨论了在不同分配器（如AVL、Bitmap、Stupid）下的性能表现，以及如何优化这些分配器的使用。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>计划重新运行测试，特别是Gabriel的PR，以验证其对性能回归的修复效果。</li><li>计划进一步调查OSD和BlueStore的行为，以确定性能问题的根本原因。</li><li>计划继续讨论和优化PG日志的存储策略，以减少对RocksDB的依赖并提高性能。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>确认Gabriel的PR将进行测试，以验证其对性能回归的修复效果。</li><li>决定进一步调查和优化PG日志的存储策略，以减少对RocksDB的依赖。</li><li>确认将继续讨论和优化PG日志和PG信息的存储策略，以提高整体性能。</li></ul><h3 id="后续行动" tabindex="-1">后续行动 <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动&quot;">​</a></h3><ul><li>重新运行性能测试，特别是Gabriel的PR。</li><li>进一步调查OSD和BlueStore的行为，以确定性能问题的根本原因。</li><li>继续讨论和优化PG日志的存储策略，以减少对RocksDB的依赖并提高性能。</li></ul><p>本次会议重点关注了Ceph存储系统的性能优化和PG日志的优化方案，为Ceph的未来发展提供了重要的技术参考和指导。</p>',9)])])}const _=l(r,[["render",o]]);export{h as __pageData,_ as default};
